// Differential checks of ScalarRepl.js against Lean, generated by leanscript --check
import * as M from "./ScalarRepl.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(0n)", () => M.test1(0n), "0", false);
check("test1(1n)", () => M.test1(1n), "0", false);
check("test1(2n)", () => M.test1(2n), "1", false);
check("test1(5n)", () => M.test1(5n), "10", false);
check("test1(13n)", () => M.test1(13n), "78", false);
check("test2(0n)", () => M.test2(0n), "0", false);
check("test2(1n)", () => M.test2(1n), "0", false);
check("test2(2n)", () => M.test2(2n), "0", false);
check("test2(5n)", () => M.test2(5n), "10", false);
check("test2(13n)", () => M.test2(13n), "286", false);
check("test3(0n, 0n)", () => M.test3(0n, 0n), "1", false);
check("test3(0n, 2n)", () => M.test3(0n, 2n), "3", false);
check("test3(0n, 13n)", () => M.test3(0n, 13n), "25", false);
check("test3(1n, 1n)", () => M.test3(1n, 1n), "1", false);
check("test3(1n, 5n)", () => M.test3(1n, 5n), "7", false);
check("test3(2n, 0n)", () => M.test3(2n, 0n), "5", false);
check("test3(2n, 2n)", () => M.test3(2n, 2n), "1", false);
check("test3(2n, 13n)", () => M.test3(2n, 13n), "21", false);
check("test3(5n, 1n)", () => M.test3(5n, 1n), "9", false);
check("test3(5n, 5n)", () => M.test3(5n, 5n), "1", false);
check("test3(13n, 0n)", () => M.test3(13n, 0n), "27", false);
check("test3(13n, 2n)", () => M.test3(13n, 2n), "23", false);
check("test3(13n, 13n)", () => M.test3(13n, 13n), "1", false);
check("test5(0n, 0n)", () => M.test5(0n, 0n), "0", false);
check("test5(0n, 2n)", () => M.test5(0n, 2n), "2", false);
check("test5(0n, 13n)", () => M.test5(0n, 13n), "13", false);
check("test5(1n, 1n)", () => M.test5(1n, 1n), "2", false);
check("test5(1n, 5n)", () => M.test5(1n, 5n), "6", false);
check("test5(2n, 0n)", () => M.test5(2n, 0n), "2", false);
check("test5(2n, 2n)", () => M.test5(2n, 2n), "4", false);
check("test5(2n, 13n)", () => M.test5(2n, 13n), "15", false);
check("test5(5n, 1n)", () => M.test5(5n, 1n), "6", false);
check("test5(5n, 5n)", () => M.test5(5n, 5n), "10", false);
check("test5(13n, 0n)", () => M.test5(13n, 0n), "13", false);
check("test5(13n, 2n)", () => M.test5(13n, 2n), "15", false);
check("test5(13n, 13n)", () => M.test5(13n, 13n), "26", false);

console.log(`ScalarRepl.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
